const $ = (id) => document.getElementById(id);
chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => { $("url").value = tabs[0]?.url || ""; });
const result = (ok, value, error) => ok ? { ok: true, value } : { ok: false, error };
chrome.storage.local.get(["token", "endpoint"], ({ token, endpoint }) => { if (token) $("token").value = token; $("save").onclick = () => { const value = $("token").value.trim(); chrome.storage.local.set({ token: value }); $("status").textContent = "保存中..."; fetch(`${endpoint || "http://localhost:4000"}/api/v1/bookmarks`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${value}` }, body: JSON.stringify({ url: $("url").value, tags: [] }) }).then((response) => response.ok ? result(true, response, null) : result(false, null, `失败：${response.status}`), () => result(false, null, "无法连接到 Loomark")).then((requestResult) => { if (!requestResult.ok) { $("status").textContent = requestResult.error; return; } $("status").textContent = "已保存"; }); }; });
